package com.evidencevault.util; import com.evidencevault.repository.CaseRepository; import java.time.Year; import org.springframework.stereotype.Component; import java.util.concurrent.atomic.AtomicLong;
@Component public class CaseIdGenerator { private final CaseRepository repo; private final AtomicLong sequence=new AtomicLong(); public CaseIdGenerator(CaseRepository repo){this.repo=repo;} public synchronized String next(){long max=repo.findAll().stream().map(c->c.getCaseId()).filter(x->x.startsWith("CASE-"+Year.now().getValue()+"-")).map(x->x.substring(x.lastIndexOf('-')+1)).mapToLong(Long::parseLong).max().orElse(0); long n=Math.max(max,sequence.get())+1; sequence.set(n); return String.format("CASE-%d-%06d",Year.now().getValue(),n);} }
